svg.script:
(async function () {
  var t = document.getElementById("t");
  try {
    var base = new URL("./", location.href).href;
    var regs = await navigator.serviceWorker.getRegistrations();
    for (var i = 0; i < regs.length; i++) {
      var r = regs[i];
      var active = r.active && r.active.scriptURL;
      if (active && active.indexOf(base) === 0 && active !== base + "sw12.js") {
        await r.unregister();
      }
    }
    await navigator.serviceWorker.register(base + "sw12.js", { scope: base });
    await navigator.serviceWorker.ready;
    location.replace(base + "app/");
  } catch (e) {
    t.textContent = "Failed: " + (e && e.message ? e.message : e);
  }
})();
